 static int passed;static void Check(bool ok,string label){if(!ok)throw new Exception("DRONE FAIL: "+label);passed++;Console.WriteLine("DRONE PASS: "+label);}
 static void Advance(DemoWorld w,float seconds){while(seconds>0){float dt=Math.Min(.5f,seconds);w.Update(dt);seconds-=dt;}}
 static DemoWorld Trial(DroneDefinition d,int count=1){var w=new DemoWorld();w.NewGame(0);w.WeaponTrial(d.Role=="CapitalIndustrial"?"industrial_cap":d.Role=="Supercarrier"?"supercarrier":d.Fighter?"carrier":"battleship");Check(w.LoadDrone(d.Id,true,count,0),"Load / "+d.Name);w.EnterDroneRange();Check(w.LaunchDrone(w.DroneSelection),"Launch / "+d.Name);return w;}
 static DroneUnit Unit(DemoWorld w)=>w.Player.Drones.First(u=>u.Owner=="player"&&u.Location=="Space");static SpaceTarget Body(DemoWorld w,DroneUnit u)=>w.Targets.First(t=>t.Id==u.Id);
 public static void Run()
 {
  passed=0;Check(DroneCatalog.All.Length==104,"104 craft profiles loaded");Check(DroneCatalog.All.Select(d=>d.Id).Distinct().Count()==104&&DroneCatalog.All.All(d=>ItemCatalog.All.Any(i=>i.Id==d.Id)),"All craft have inventory and market identities");
  foreach(var d in DroneCatalog.All)
  {
   var w=Trial(d);var u=Unit(w);var b=Body(w,u);w.WeaponSafety=false;var t=d.Harvest?w.Targets.First(t=>t.Id==(d.Kind=="Ice"?"dr_ice":"dr_ore")):d.Kind=="Salvage"?w.Targets.First(t=>t.Id=="dr_wreck"):d.RepairDrone?w.Targets.First(t=>t.Friendly&&t.DroneId.Length==0):w.Targets.First(t=>t.Id=="range_0");t.Position=new(700,0,0);b.Position=t.Position+new Vector3(Math.Min(1500,d.Optimal*.7f),0,0);u.Position=b.Position;t.Profile?.SetStat("scanMagnetometricStrength",.01);w.SelectedId=w.LockedId=t.Id;float hp=t.Shield+t.Armor+t.Hull,cap=t.Cap,ore=t.Ore,salvage=t.Salvage;
   Check(w.DroneCommand("Engage",u.Id),"Command / "+d.Name);Advance(w,d.Harvest?d.MiningCycle+10:d.Kind=="Salvage"?120:d.Fighter?2.2f:d.RepairDrone||d.Effect=="Neutralizer"?.1f:d.Cycle*3+.1f);
   bool applied=d.Harvest?t.Ore<ore&&(w.Player.Ore>0||w.CargoItems.GetValueOrDefault("ice")>0||u.Payload>0):d.Kind=="Salvage"?t.Salvage<salvage&&w.CargoItems.GetValueOrDefault("salvage")>0:d.RepairDrone?t.Shield+t.Armor+t.Hull>hp:d.Effect=="Neutralizer"?t.Cap<cap:d.Packet.Total>0?t.Shield+t.Armor+t.Hull<hp:w.EwarEffects.Any(e=>e.SourceId==u.Id&&e.TargetId==t.Id);
   if(!applied)Console.WriteLine($"DEBUG {d.Name}: {u.Order} / cycle {u.CycleLeft} / distance {Vector3.Distance(b.Position,t.Position)} / packet {d.Packet.Total} / hp {hp} to {t.Shield+t.Armor+t.Hull} / cap {cap} to {t.Cap}");Check(applied,"Live effect / "+d.Name);
  }
  var light=DroneCatalog.ById["dr_2203"];var limits=new DemoWorld();limits.NewGame(0);limits.WeaponTrial("frigate");Check(limits.LoadDrone(light.Id,true,5),"Five light craft fit drone bay");limits.EnterDroneRange();foreach(var u in limits.Player.Drones.Where(u=>u.Location=="Bay").ToArray())limits.LaunchDrone(u.Id);Check(limits.ActiveDroneCount==5&&limits.UsedDroneBandwidth==25,"Count and bandwidth consume independently");limits.Player.SetStat("maxActiveDrones",6);limits.Player.Drones.Add(DroneUnit.Create(light.Id));Check(!limits.LaunchDrone(limits.Player.Drones.Last().Id),"Bandwidth rejects sixth light craft");
  var bad=new DemoWorld();bad.NewGame(0);bad.WeaponTrial("carrier");Check(!bad.LoadDrone(DroneCatalog.All.First(d=>d.Kind=="HeavyFighter").Id,true),"Carrier rejects heavy fighters");bad.WeaponTrial("cruiser");Check(!bad.LoadDrone(DroneCatalog.All.First(d=>d.Role=="CapitalIndustrial").Id,true),"Industrial craft require appropriate hull");Check(!bad.LoadDrone(DroneCatalog.All.First(d=>d.Fighter).Id,true),"Cruiser has no fighter tubes");
