  var sentry=Trial(DroneCatalog.All.First(d=>d.Kind=="Sentry"));var su=Unit(sentry);var sb=Body(sentry,su);sb.Position=new(8000,0,0);sentry.DroneCommand("Return",su.Id);Advance(sentry,1);Check(sb.Position==new Vector3(8000,0,0)&&su.Location=="Space","Sentries remain stationary during recall");sentry.Player.Position=sb.Position;Check(sentry.ScoopDrone(su.Id),"Sentry can be scooped nearby");
  foreach(var d in DroneCatalog.All.Where(d=>d.Fighter))
