   var w=Trial(d,Math.Min(2,d.SquadronSize));var u=Unit(w);Advance(w,2.1f);w.WeaponSafety=false;var b=Body(w,u);for(int slot=1;slot<d.Abilities.Length;slot++){var a=d.Abilities[slot];var t=a.Kind=="Tackle"?w.Targets.First(t=>t.DroneId.Length>0&&!t.Friendly):w.Targets.First(t=>t.Id=="range_0");w.SelectedId=w.LockedId=t.Id;b.Position=t.Position+new Vector3(10,0,0);w.Player.ManualPoint=b.Position+new Vector3(25000,0,0);u.AbilityCooldowns[slot]=0;Check(w.FighterAbility(u.Id,slot),"Ability / "+d.Name+" / "+a.Kind);Check(a.Kind=="Evade"?u.EvasionLeft>0:a.Kind is "MWD" or "AB"?u.BoostLeft>0:a.Kind=="MJD"?u.JumpLeft>0:a.Kind=="Tackle"?w.EwarFor(t.Id).WarpStrength>0&&w.EwarFor(t.Id).Speed<1:a.Kind=="Sacrifice"?u.Count==0&&u.Location=="Destroyed":w.MissilesInFlight.Any(m=>m.Owner==u.Id&&m.Bomb==(a.Kind=="Bomb")),"Ability produces real effect / "+a.Kind);}
  }
  var fd=DroneCatalog.All.First(d=>d.Kind=="AttackFighter");var fighter=Trial(fd,3);var fu=Unit(fighter);float credits=fighter.Credits;fighter.ApplyDroneTestDamage(fu.Id,100000);Check(fu.Count==2&&Body(fighter,fu).Alive&&fighter.Credits==credits,"Fighter losses remove one member without bounty");Advance(fighter,2.1f);var target=fighter.Targets.First(t=>t.Id=="range_0");Body(fighter,fu).Position=target.Position+new Vector3(10,0,0);fighter.SelectedId=fighter.LockedId=target.Id;int charges=fu.AbilityCharges[2];Check(fighter.FighterAbility(fu.Id,2)&&fu.AbilityCharges[2]==charges-1,"Salvo consumes one magazine charge");Check(!fighter.FighterAbility(fu.Id,2),"Cooldown rejects immediate repeated salvo");fu.AbilityCharges[2]=0;Check(fighter.RearmFighter(fu.Id),"Ability rearm command accepted");Advance(fighter,fd.Abilities[2].Rearm+.1f);Check(fu.AbilityCharges[2]==fd.Abilities[2].Charges,"Independent ability reload replenishes charges");
  var repair=Trial(DroneCatalog.All.First(d=>d.Kind=="ShieldRepair"));repair.SelectedId=repair.LockedId="range_0";var victim=repair.Targets.First(t=>t.Id=="range_0");victim.Shield*=.5f;victim.RemoteRepairMultiplier=0;victim.DriveLockout=60;float before=victim.Shield;repair.DroneCommand("Engage",Unit(repair).Id);Advance(repair,8);Check(victim.Shield==before,"Repair interdiction blocks assistance");repair.SelectedId=repair.LockedId="player";Check(!repair.DroneCommand("Engage",Unit(repair).Id),"Repair drones cannot repair owner");
  var reserve=new DemoWorld();reserve.NewGame(0);reserve.WeaponTrial("carrier");float stock=reserve.ItemCount(fd.Id,true);Check(reserve.StoreFighterReserve(fd.Id,fd.SquadronSize),"Spare fighters stow from station inventory");var rs=reserve.Player.Drones.First(u=>u.Location=="Reserve");Check(reserve.ItemCount(fd.Id,true)==stock-fd.SquadronSize&&reserve.Player.FighterBayUsed==fd.Volume*fd.SquadronSize,"Spare count and volume conserved");Check(reserve.ReplenishFighter(rs.Id,0),"Reserve loads an empty tube");var squad=reserve.Player.Drones.First(u=>u.Location=="Bay"&&u.Definition.Fighter);reserve.StoreFighterReserve(fd.Id,fd.SquadronSize);rs=reserve.Player.Drones.First(u=>u.Location=="Reserve");reserve.EnterDroneRange();reserve.LaunchDrone(squad.Id);Check(!reserve.ReplenishFighter(rs.Id,0),"Active tubes cannot replenish");reserve.ApplyDroneTestDamage(squad.Id,100000);var body=Body(reserve,squad);body.Position=reserve.Player.Position+new Vector3(100,0,0);body.Armor=fd.Armor*.5f;reserve.DroneCommand("Return",squad.Id);reserve.Update(.1f);Check(reserve.ReplenishFighter(rs.Id,0)&&squad.Count==fd.SquadronSize&&squad.Armor==fd.Armor*.5f&&rs.Count==fd.SquadronSize-1,"Space replenishment preserves damage and consumes exact spare count");Check(reserve.UnloadDrone(squad.Id)&&squad.Location=="Reserve","Landed squadron unloads to onboard reserves");Check(reserve.ReplenishFighter(squad.Id,1)&&reserve.Player.Drones.Any(u=>u.Tube==1&&u.Armor==fd.Armor*.5f),"Damaged fighter integrity survives tube transfer");reserve.Save();var restored=new DemoWorld();Check(restored.Load()&&restored.Player.Drones.Any(u=>u.Location=="Reserve"&&u.Count==fd.SquadronSize-1),"Save/load retains reserve fighter counts");
  var fit=new DemoWorld();fit.NewGame(0);fit.WeaponTrial("cruiser");fit.LoadDrone(light.Id,true,5);var medium=DroneCatalog.ById["dr_2173"];fit.LoadDrone(medium.Id,true,5);Check(Math.Abs(fit.Player.BayDroneDps-5*medium.Packet.Total/medium.Cycle)<.01,"Optimal fitting DPS flight respects count and bandwidth");fit.EnterDroneRange();foreach(var u in fit.Player.Drones.Where(u=>u.TypeId==medium.Id&&u.Location=="Bay").ToArray())fit.LaunchDrone(u.Id);Check(Math.Abs(fit.Player.BayDroneDps-5*light.Packet.Total/light.Cycle)<.01&&fit.Player.ActiveDroneDps>0,"Bay DPS excludes launched craft");
  var ec=Trial(DroneCatalog.All.First(d=>d.Kind=="ECM"));var eu=Unit(ec);var et=ec.Targets.First(t=>t.Id=="range_0");et.Profile!.SetStat("scanMagnetometricStrength",.01);Body(ec,eu).Position=et.Position+new Vector3(1000,0,0);ec.SelectedId=ec.LockedId=et.Id;ec.DroneCommand("Engage",eu.Id);Advance(ec,.1f);Check(ec.EwarFor(et.Id).Jammers.Contains(eu.Id)&&ec.CanLock(et.Id,eu.Id)&&!ec.CanLock(et.Id,"player"),"ECM retaliation targets the drone jammer rather than its owner");
  var assist=Trial(light);var au=Unit(assist);var friendly=assist.Targets.First(t=>t.Friendly&&t.DroneId.Length==0);friendly.LockId="range_0";assist.SelectedId=friendly.Id;Check(assist.DroneCommand("Assist",au.Id),"Assist accepts a friendly external ship");assist.Update(.1f);Check(au.Order=="Attack"&&au.TargetId=="range_0","Assist follows the friendly target");assist.Targets.First(t=>t.Id=="range_1").LockId=friendly.Id;assist.SelectedId=friendly.Id;Check(assist.DroneCommand("Guard",au.Id),"Guard assignment accepted");assist.Update(.1f);Check(au.TargetId=="range_1","Guard reacts to friendly ship aggressor");
  var mine=Trial(DroneCatalog.All.First(d=>d.Kind=="Mine"));var mu=Unit(mine);var mt=mine.Targets.First(t=>t.Id=="dr_ore");mt.Position=new(500,0,0);Body(mine,mu).Position=mt.Position+new Vector3(50,0,0);mine.SelectedId=mt.Id;Check(mine.DroneCommand("MineOnce",mu.Id),"One-cycle mining accepted");float oreBefore=mt.Ore;Advance(mine,mu.Definition.MiningCycle*.5f);Check(mt.Ore==oreBefore&&mu.HarvestCycling,"Mining waits for full cycle before extracting");mine.Save();var mined=new DemoWorld();Check(mined.Load()&&mined.Player.Drones.Any(u=>u.Id==mu.Id&&u.HarvestCycling&&u.CycleLeft>0),"In-progress mining cycle survives save/load");Advance(mine,mu.Definition.MiningCycle+10);Check(mt.Ore<oreBefore&&mu.Order=="Orbit"&&mine.Player.Ore>0,"One-cycle mining delivers yield then stops");
  var ice=Trial(DroneCatalog.All.First(d=>d.Kind=="Ice"));var iu=Unit(ice);var it=ice.Targets.First(t=>t.Id=="dr_ice");it.Position=new(500,0,0);Body(ice,iu).Position=it.Position+new Vector3(50,0,0);ice.SelectedId=it.Id;ice.DroneCommand("MineOnce",iu.Id);Advance(ice,iu.Definition.MiningCycle+10);Check(ice.CargoItems.GetValueOrDefault("ice")==1&&it.Ore==49000,"Ice extraction produces one whole 1000 m3 block");
  var sal=Trial(DroneCatalog.All.First(d=>d.Kind=="Salvage"));var slu=Unit(sal);var wreck=sal.Targets.First(t=>t.Kind==TargetKind.Wreck);Body(sal,slu).Position=wreck.Position+new Vector3(50,0,0);sal.SelectedId="";Check(sal.DroneCommand("Engage",slu.Id),"Auto salvage finds a wreck without selection");Advance(sal,slu.Definition.Cycle*.5f);Check(wreck.Salvage==4,"Salvage waits for complete access cycle");Advance(sal,120);Check(wreck.Salvage==0&&sal.CargoItems.GetValueOrDefault("salvage")==4,"Successful salvage recovers fixed contents without yield inflation");
  var persisted=Trial(light);var du=Unit(persisted);du.Group="Saved group";du.Order="Return";du.Payload=3;Body(persisted,du).Armor=light.Armor*.25f;persisted.Player.DroneAggressive=true;persisted.Save();var savedWorld=new DemoWorld();Check(savedWorld.Load(),"Deployed craft save loads");var savedUnit=savedWorld.Player.Drones.First(u=>u.Id==du.Id);Check(savedUnit.Group=="Saved group"&&savedUnit.Order=="Return"&&savedUnit.Payload==3&&savedUnit.Armor==light.Armor*.25f&&savedWorld.Targets.Any(t=>t.DroneId==du.Id)&&savedWorld.Player.DroneAggressive,"Identity, group, order, payload, damage, body and behavior persist");
  var reload=Trial(fd,3);var rlu=Unit(reload);Advance(reload,2.1f);reload.SelectedId=reload.LockedId="range_0";var rt=reload.Targets.First(t=>t.Id=="range_0");Body(reload,rlu).Position=rt.Position+new Vector3(1000,0,0);rlu.AbilityCharges[2]=0;reload.DroneCommand("Engage",rlu.Id);Check(reload.RearmFighter(rlu.Id),"Magazine reload starts alongside primary attack");float rhp=rt.Shield+rt.Armor+rt.Hull;Advance(reload,.2f);Check(rlu.AbilityReloads[2]>0&&rt.Shield+rt.Armor+rt.Hull<rhp,"Ability reload does not suspend primary weapon damage");
